test "a cheap desk offer matches a desk request with an overlapping move-in week (AE2)" {
    offer = Post(
        owner_root="jae",
        kind="offer",
        category="furniture",
        title="Desk",
        price=25.0,
        available_from="2026-08-18",
        available_until="2026-08-25",
        area="Central Campus"
    );
    request = Post(
        owner_root="mina",
        kind="request",
        category="furniture",
        title="Need a desk",
        price=50.0,
        available_from="2026-08-20",
        available_until="2026-08-22",
        area="Central Campus"
    );
    m = match_pair(offer, request, "2026-08-01");
    assert m is not None;
    assert "Dates overlap" in m.reasons;
    assert "$25 is within the $50 budget" in m.reasons;
    assert "Both in Central Campus" in m.reasons;
    assert match_pair(request, offer, "2026-08-01") is not None;
}

test "hard filters reject wrong category, same kind, same student, budget and dates" {
    desk = Post(
        owner_root="jae", kind="offer", category="furniture", title="Desk", price=60.0
    );
    assert match_pair(
        desk,
        Post(owner_root="mina", kind="request", category="essentials", title="x"),
        "2026-08-01"
    )
        is None;
    assert match_pair(
        desk,
        Post(
            owner_root="mina", kind="offer", category="furniture", title="x", price=5.0
        ),
        "2026-08-01"
    )
        is None;
    assert match_pair(
        desk,
        Post(owner_root="jae", kind="request", category="furniture", title="x"),
        "2026-08-01"
    )
        is None;
    assert match_pair(
        desk,
        Post(
            owner_root="mina",
            kind="request",
            category="furniture",
            title="x",
            price=50.0
        ),
        "2026-08-01"
    )
        is None;
    late = Post(
        owner_root="jae",
        kind="offer",
        category="furniture",
        title="Desk",
        price=5.0,
        available_from="2026-08-01",
        available_until="2026-08-10"
    );
    early = Post(
        owner_root="mina",
        kind="request",
        category="furniture",
        title="x",
        available_from="2026-08-11"
    );
    assert match_pair(late, early, "2026-08-01") is None;
}

test "windows touching on one day overlap; a day apart do not" {
    a = Post(
        owner_root="jae",
        kind="offer",
        category="furniture",
        title="Desk",
        free=True,
        available_from="2026-08-01",
        available_until="2026-08-10"
    );
    touch = Post(
        owner_root="mina",
        kind="request",
        category="furniture",
        title="x",
        available_from="2026-08-10"
    );
    apart = Post(
        owner_root="mina",
        kind="request",
        category="furniture",
        title="x",
        available_from="2026-08-11"
    );
    assert match_pair(a, touch, "2026-08-01") is not None;
    assert match_pair(a, apart, "2026-08-01") is None;
}

test "without a price on both sides there is no budget filter and no budget reason" {
    offer = Post(
        owner_root="jae", kind="offer", category="essentials", title="Lamp", price=15.0
    );
    request = Post(
        owner_root="mina", kind="request", category="essentials", title="Lamp please"
    );
    m = match_pair(offer, request, "2026-08-01");
    assert m is not None and not any(["budget" in r for r in m.reasons]);
}

test "two ride requests from DTW within two hours match each other" {
    a = Post(
        owner_root="jae",
        kind="request",
        category="service",
        title="Ride",
        route_from="DTW",
        route_to="Ann Arbor",
        available_from="2026-08-20",
        time_from="14:00",
        time_to="15:00"
    );
    b = Post(
        owner_root="mina",
        kind="request",
        category="service",
        title="Ride",
        route_from="Detroit Metro Airport",
        route_to="ann arbor",
        available_from="2026-08-20",
        time_from="16:30"
    );
    m = match_pair(a, b, "2026-08-01");
    assert m is not None and "Times are 90 minutes apart" in m.reasons;
    far = Post(
        owner_root="mina",
        kind="request",
        category="service",
        title="Ride",
        route_from="DTW",
        route_to="Ann Arbor",
        available_from="2026-08-20",
        time_from="19:00"
    );
    assert match_pair(a, far, "2026-08-01") is None;
    other_day = Post(
        owner_root="mina",
        kind="request",
        category="service",
        title="Ride",
        route_from="DTW",
        route_to="Ann Arbor",
        available_from="2026-08-21",
        time_from="14:00"
    );
    assert match_pair(a, other_day, "2026-08-01") is None;
}

test "a ride never matches a non-ride service" {
    ride = Post(
        owner_root="jae",
        kind="request",
        category="service",
        title="Ride",
        route_from="DTW",
        route_to="Ann Arbor"
    );
    moving = Post(
        owner_root="mina", kind="offer", category="service", title="Help moving"
    );
    assert match_pair(ride, moving, "2026-08-01") is None;
}

test "housing arrangements must agree when both posts state one" {
    sublet = Post(
        owner_root="jae",
        kind="offer",
        category="housing",
        title="Room",
        price=700.0,
        arrangement="sublet"
    );
    wants_sublet = Post(
        owner_root="mina",
        kind="request",
        category="housing",
        title="x",
        price=800.0,
        arrangement="sublet"
    );
    wants_lease = Post(
        owner_root="mina",
        kind="request",
        category="housing",
        title="x",
        price=800.0,
        arrangement="new lease"
    );
    both = match_pair(sublet, wants_sublet, "2026-08-01");
    assert both is not None and "Both want a sublet" in both.reasons;
    assert match_pair(sublet, wants_lease, "2026-08-01") is None;
}

test "done or expired posts never match" {
    offer = Post(
        owner_root="jae",
        kind="offer",
        category="furniture",
        title="Desk",
        free=True,
        expires_on="2026-08-05"
    );
    request = Post(owner_root="mina", kind="request", category="furniture", title="x");
    assert match_pair(offer, request, "2026-08-05") is None;
    request.done = True;
    assert match_pair(offer, request, "2026-08-01") is None;
}

test "every reason is a fact present on the posts" {
    offer = Post(
        owner_root="jae",
        kind="offer",
        category="furniture",
        title="Desk",
        price=25.0,
        available_from="2026-08-18",
        area="Kerrytown"
    );
    request = Post(
        owner_root="mina",
        kind="request",
        category="furniture",
        title="x",
        price=50.0,
        available_from="2026-08-18",
        area="North Campus"
    );
    m = match_pair(offer, request, "2026-08-01");
    assert m is not None;
    assert not any(["Kerrytown" in r or "North Campus" in r for r in m.reasons]);
    for r in m.reasons {
        assert r in ["Dates overlap", "$25 is within the $50 budget"];
    }
}

test "only DTW names count as DTW; other airports stay distinct" {
    assert place("DTW") == "dtw" and place("Detroit Metro Airport") == "dtw";
    assert place("O'Hare airport") != "dtw";
    assert place("the airport") != "dtw";
    assert place("Ann Arbor") == "ann arbor";
}

test "an item available until a date overlaps a need earlier than that date" {
    desk = Post(
        owner_root="jae",
        kind="offer",
        category="furniture",
        title="Wooden desk",
        price=30.0,
        available_until="2026-10-03"
    );
    weekend = Post(
        owner_root="mina",
        kind="request",
        category="furniture",
        title="Desk",
        price=40.0,
        available_from="2026-09-27",
        available_until="2026-09-28"
    );
    m = match_pair(desk, weekend, "2026-09-26");
    assert m is not None and "Dates overlap" in m.reasons;
    late = Post(
        owner_root="mina",
        kind="request",
        category="furniture",
        title="Desk",
        available_from="2026-10-10"
    );
    assert match_pair(desk, late, "2026-09-26") is None;
}
