    has amount: float = 0.0;
    has organization: str = "Community";
    has approved: bool = False;
    has claimed: bool = False;
    has claimant_name: str = "";
    has claim_time: str = "";
    has created_at: str = "";
}

node OrganizationProfile {
    has name: str = "";
}

def:pub list_organizations() -> list[str] {
    names: list[str] = [];
    for account_root in allroots() {
        for profile in [account_root -->][?:OrganizationProfile] {
            if profile.name not in names { names.append(profile.name); }
        }
    }
    return names;
}

def:priv register_organization(name: str) -> str {
    clean_name = name.strip();
    if clean_name == "" { return ""; }
    own_profiles = [root -->][?:OrganizationProfile];
    if len(own_profiles) > 0 { return own_profiles[0].name; }
    for account_root in allroots() {
        for profile in [account_root -->][?:OrganizationProfile] {
            if profile.name.lower() == clean_name.lower() { return ""; }
        }
    }
    root ++> OrganizationProfile(name=clean_name);
    return clean_name;
}

def:priv my_organization() -> str {
    profiles = [root -->][?:OrganizationProfile];
    if len(profiles) > 0 { return profiles[0].name; }
    return "";
}

def:priv list_my_donations() -> list[DonationItem] {
    profiles = [root -->][?:OrganizationProfile];
    if len(profiles) == 0 { return []; }
    org_name = profiles[0].name;
    return [item for item in [root.shared -->][?:DonationItem] if item.organization == org_name];
}

def:pub list_donations() -> list[DonationItem] {
    return [item for item in [root.shared -->][?:DonationItem] if item.approved and not item.claimed];
}

def:pub submit_donation(title: str, description: str, donor: str, amount: float, organization: str) -> DonationItem | None {
    registered = False;
    for account_root in allroots() {
        for profile in [account_root -->][?:OrganizationProfile] {
            if profile.name == organization { registered = True; }
        }
    }
    if not registered { return None; }
    item = root.shared ++> DonationItem(
        title=title,
        description=description,
        donor=donor if donor != "" else "Anonymous",
        amount=amount,
        organization=organization,
        approved=False,
        claimed=False
    );
    grant(item, level=WritePerm);
    return item;
}

def:priv approve_donation(donation_id: str) -> bool {
    profiles = [root -->][?:OrganizationProfile];
    if len(profiles) == 0 { return False; }
    for item in [root.shared -->][?:DonationItem] {
        if jid(item) == donation_id and item.organization == profiles[0].name and not item.claimed {
            item.approved = True;
            return True;
        }
    }
    return False;
}

def:pub claim_donation(donation_id: str, organization: str, claim_time: str) -> bool {
    if organization.strip() == "" or claim_time.strip() == "" { return False; }
    for item in [root.shared -->][?:DonationItem] {
        if jid(item) == donation_id and item.approved and not item.claimed {
            item.claimed = True;
            item.claimant_name = organization.strip();
            item.claim_time = claim_time.strip();
            return True;
        }
    }
    return False;
}
