                        onEdit={openEditEntry}
                    />
                </div>
            }   }
            <EntryDialog
                open={entryOpen}
                editing={entryEditing}
                form={entryForm}
                members={members}
                projects={projects}
                saving={entrySaving}
                onField={entryField}
                onOpenChange={lambda (o: bool) { entryOpen = o; }}
                onSave={saveEntry}
            />
        </div>;
}

