        ov_blurb = "";
        ov_tip = "";
        if it.id in overviews {
            raw: any = overviews[it.id];
            try {
                b = raw["blurb"];
                if b {
                    ov_blurb = str(b);
                }
                t = raw["tip"];
                if t {
                    ov_tip = str(t);
                }
            } except Exception {
                if raw {
                    ov_blurb = str(raw);
                }
            }
        }
        html = map_popup_html(it, dark, ov_blurb, ov_tip);
        if len(it.path) > 1 {
            line: any = new(
                gm.Polyline,
                {
                    "map": map_obj,
                    "path": [{"lat": p[0], "lng": p[1]} for p in it.path],
                    "strokeColor": col,
                    "strokeOpacity": 0.8,
                    "strokeWeight": 5
                }
            );
            bind_line_click(line, info, map_obj, html);
