"""GitHub state on a kanban card: the linked issue, its PR, and the nudge. A
merged PR *suggests* Done here; auto-done repos move the card server-side
on sync instead, from the same statuses (MERGE_SUGGEST_STATUSES)."""

import from ...models { TaskView }
import from ...constants { MERGE_SUGGEST_STATUSES }
import from ..ui.badge { Badge }
import from ..ui.button { Button }

# Merged and closed mean opposite things on GitHub, so they never share a
# tint. Anything unrecognised falls back to the neutral outline.
glob PR_TINT: dict[str, str] = {
         "open": "border-success/40 bg-success/10 text-success",
         "draft": "border-border bg-muted text-muted-foreground",
         "merged": "border-primary/40 bg-primary/10 text-primary",
         "closed": "border-destructive/40 bg-destructive/10 text-destructive"
     };

# Columns where "the PR merged" is news. A card already in Done or Backlog
# does not need telling.
def:pub GitHubChip(task: TaskView, onMarkDone: Callable[[str], None]) -> JsxElement {
    issueTint = (
        "border-border bg-muted/60 text-muted-foreground line-through"
            if task.gh_issue_state == "closed"
            else "border-border bg-card text-foreground hover:bg-accent"
    );
    prLabel = "PR " + task.pr_state;
    prTitle = (
        (task.gh_repo + " #" + str(task.pr_number)) if task.pr_number > 0 else prLabel
    );
    suggestDone = task.pr_state == "merged" and task.status in MERGE_SUGGEST_STATUSES;

    return
        <div className="space-y-1.5">
            <div className="flex flex-wrap items-center gap-1">
                {if task.gh_issue_number > 0 {
                    <a
                        key="issue"
                        href={task.issue_link}
                        target="_blank"
                        rel="noreferrer"
                        title={task.gh_repo + " #" + str(task.gh_issue_number)}
                        # The card itself opens the task dialog on click.
                        onClick={lambda (e: MouseEvent) { e.stopPropagation(); }}
                        className={"inline-flex h-5 items-center rounded-full border px-2 text-xs font-medium transition-colors "
                            + issueTint}
                    >
                        {"#" + str(task.gh_issue_number)}
                    </a>
                }}
                {if task.pr_state {
                    <Badge
                        key="pr"
                        variant="outline"
                        title={prTitle}
                        className={PR_TINT.get(
                            task.pr_state, "border-border bg-card text-muted-foreground"
                        )
                            + " h-5 rounded-full"}
                    >
                        {prLabel}
                    </Badge>
                }}
                {if task.gh_sub_total > 0 {
                    <Badge
                        key="family"
                        variant="outline"
                        title={"Sub-issues: "
                            + str(task.gh_sub_done)
                            + " of "
                            + str(task.gh_sub_total)
                            + " done"}
                        className={(
                            "border-success/40 bg-success/10 text-success"
                                if task.gh_sub_done == task.gh_sub_total
                                else "border-primary/40 bg-primary/10 text-primary"
                        )
                            + " h-5 rounded-full tabular-nums"}
                    >
                        {"⌗ " + str(task.gh_sub_done) + "/" + str(task.gh_sub_total)}
                    </Badge>
                }}
                {if task.gh_parent_number > 0 {
                    <Badge
                        key="parent"
                        variant="outline"
                        title={"Part of "
                            + task.gh_parent_repo
                            + " #"
                            + str(task.gh_parent_number)}
                        className="h-5 rounded-full border-border bg-card text-muted-foreground"
                    >
                        {"↳ #" + str(task.gh_parent_number)}
                    </Badge>
                }}
            </div>
            {if suggestDone {
                <div
                    key="suggest"
                    className="flex items-center justify-between gap-2 rounded-md border border-primary/30 bg-primary/5 px-2 py-1 text-xs"
                >
                    <span className="text-muted-foreground">PR merged.</span>
                    <Button
                        variant="ghost"
                        size="xs"
                        onClick={lambda (e: MouseEvent) {
                            e.stopPropagation();
                            onMarkDone(task.id);
                        }}
                    >
                        Mark done
                    </Button>
                </div>
            }}
        </div>;
}

"""flowline - persisted graph model and shared helpers. EVERY node/edge/obj
archetype lives HERE and must not move: archetype identity includes the module
path, so relocating a declaration orphans persisted data.
"""

# jobj raises on a malformed/unknown anchor id — a stale client jid must
# no-op the walker, not 500 the request.
def resolve(anchor_id: str) -> any {
    if not anchor_id {
        return None;
    }
    try {
        return jobj(anchor_id);
    } except Exception {
        return None;
    }
}

# v3 hook: when multi-PM orgs land, grant `fresh` to every collaborating
# root here. Deliberately a no-op while one account == one organization.
def on_attached(holder: any, fresh: any) -> None {
    return;
}

# "org/repo" and nothing else: repo names land in api.github.com paths, so
# `..`, `?` or `#` could redirect a request. Pure string work, so it lives
# here rather than in the Python-importing helpers, shared by storage and API.
def valid_full_name(full_name: str) -> bool {
    if full_name.count("/") != 1 {
        return False;
    }
    for part in full_name.split("/") {
        if not part or len(part) > 100 {
            return False;
        }
        for ch in part {
            if not (ch.isalnum() or ch in "-_.") {
                return False;
            }
        }
    }
    return True;
}

# Parentage check: does this node hang directly off the caller's root?
# jobj/jid resolution is NOT authorization — every jid-addressed mutation
# calls this first, or a guessed/leaked jid from another account would be
# mutable. The account IS the organization, so "my root" is the tenant line.
def owned(holder: any, target: any) -> bool {
    for owner in [target<--] {
        if jid(owner) == jid(holder) {
            return True;
        }
    }
    return False;
}

# ---------------------------------------------------------------- archetypes

node Project {
    has name: str,
        description: str = "",
        active: bool = True;
}

node Member {
    has name: str,
        roles: list[str] = [],
        email: str = "",
        github_username: str = "",
        tags: list[str] = [],
        # A manager-picked avatar colour (a step colour key). Empty falls
        # back to the hue hashed from the name, so existing members keep
        # the colour they already show.
        color: str = "",
        active: bool = True;
}

node Repo {
    has full_name: str,
        # Auto-file new issues onto the entry step on every GitHub sync.
        # The cursor is the newest `updated_at` seen, so each sync asks
        # GitHub only for what changed since; empty means backfill.
        auto_sync: bool = False,
        issue_cursor: str = "",
        # Merged PR moves the linked card to the done step on sync.
        auto_done: bool = False;
}

node Task {
    has title: str,
        category: str,
        priority: str,
        # The board column this task sits in, as a WorkflowStep jid. Empty on
        # every task written before flow lines existed, and on any task whose
        # step was deleted; the board falls back to `status` for those, so
        # this is additive and old rows keep working.
        step_id: str = "",
        # Legacy column AND the semantic signal the rest of the app reads
        # ("Done" is terminal, "Blocked" needs attention). A move keeps it in
        # step with the step's kind, so insights, GitHub sync and the
        # assistant never have to learn about steps.
        status: str = "Backlog",
        due_date: str = "",
        notes: str = "",
        issue_link: str = "",
        pr_link: str = "",
        reviewer_id: str = "",
        reviewer_name: str = "",
        review_due: str = "",
        created_at: str = "",
        updated_at: str = "",
        sort_order: float = 0.0,
        # Free labels beside the single category; GitHub issue labels land
        # here at import. Additive with a default, so old rows keep working.
        tags: list[str] = [],
        # Effort estimate in the org's own unit (points or hours). 0 means
        # unestimated; additive with a default, so old rows read as such.
        estimate: float = 0.0,
        # GitHub identity. issue_link/pr_link stay the human URLs anyone can
        # paste by hand; these are the machine key the API syncs against.
        # gh_issue_number == 0 means "not linked to a real issue".
        gh_repo: str = "",
        gh_issue_number: int = 0,
        gh_issue_state: str = "",
        gh_synced_at: str = "",
        # GitHub's updated_at of the newest item applied here; the sync keeps
        # it monotonic so an older event can never roll a newer one back.
        gh_updated_at: str = "",
        # GitHub sub-issue family, stamped by the sync. A parent carries its
        # summary counts; a child carries its parent's identity. Fields, not
        # edges: an edge would cost a traversal per row in every list.
        gh_parent_repo: str = "",
        gh_parent_number: int = 0,
        gh_sub_total: int = 0,
        gh_sub_done: int = 0,
        pr_number: int = 0,
        pr_state: str = "";

    # One task's view, hopping its own edges. Fine for a single task; for a
    # list use hydrate_views, which gets the same links in a few traversals
    # instead of three per row.
    def to_view -> TaskView {
        assignee_ids: list[str] = [];
        assignee_names: list[str] = [];
        for a in [self->:AssignedTo:->] {
            assignee_ids.append(jid(a));
            assignee_names.append(a.name);
        }
        project_id = "";
        project_name = "";
        projects = [self->:ForProject:->];
        if projects {
            project_id = jid(projects[0]);
            project_name = projects[0].name;
        }
        milestone_id = "";
        milestone_name = "";
        stones = [self->:InMilestone:->];
        if stones {
            milestone_id = jid(stones[0]);
            milestone_name = stones[0].title;
        }
        return self.view_with(
            assignee_ids,
            assignee_names,
            project_id,
            project_name,
            milestone_id,
            milestone_name
        );
    }

    # The view given links the caller already has. The field list lives here
    # once, so to_view and hydrate_views cannot drift apart.
    def view_with(
        assignee_ids: list[str],
        assignee_names: list[str],
        project_id: str,
        project_name: str,
        milestone_id: str,
        milestone_name: str
    ) -> TaskView {
        return TaskView(
            id=jid(self),
            title=self.title,
            category=self.category,
            tags=self.tags,
            estimate=self.estimate,
            priority=self.priority,
            status=self.status,
            step_id=self.step_id,
            due_date=self.due_date,
            notes=self.notes,
            created_at=self.created_at,
            updated_at=self.updated_at,
            sort_order=self.sort_order,
            assignee_ids=assignee_ids,
            assignee_names=assignee_names,
            issue_link=self.issue_link,
            pr_link=self.pr_link,
            reviewer_id=self.reviewer_id,
            reviewer_name=self.reviewer_name,
            review_due=self.review_due,
            project_id=project_id,
            project_name=project_name,
            milestone_id=milestone_id,
            milestone_name=milestone_name,
            gh_repo=self.gh_repo,
            gh_issue_number=self.gh_issue_number,
            gh_issue_state=self.gh_issue_state,
            gh_synced_at=self.gh_synced_at,
            gh_parent_repo=self.gh_parent_repo,
            gh_parent_number=self.gh_parent_number,
            gh_sub_total=self.gh_sub_total,
            gh_sub_done=self.gh_sub_done,
            pr_number=self.pr_number,
            pr_state=self.pr_state
        );
    }
}

